WITH filtered AS (SELECT id, device_code, reading_ts, humidity, firmware, DAYOFWEEK(reading_ts) AS reading_ts_dayofweek FROM device_readings WHERE humidity > 68), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM filtered), islands AS (SELECT id, device_code, reading_ts, humidity, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT device_code, COUNT(*) FILTER (WHERE device_code = 'DV-02') AS dv_02_rows, APPROX_PERCENTILE(humidity, ARRAY(0.25, 0.5, 0.75)) AS humidity_quartiles, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, ROUND(AVG(humidity), 2) AS avg_humidity, COUNT(*) FILTER (WHERE device_code = 'DV-01') AS dv_01_rows FROM islands GROUP BY device_code;
